(()=>{let mode='light';try{mode=localStorage.getItem('vector-theme')==='dark'?'dark':'light';}catch{}const docs=new Set();function paint(doc){doc.documentElement.dataset.cadTheme=mode;doc.querySelectorAll('[data-theme-toggle]').forEach(b=>{b.textContent=mode==='dark'?'Light mode':'Dark mode';b.setAttribute('aria-pressed',String(mode==='dark'));});}function attach(doc){if(docs.has(doc))return;docs.add(doc);paint(doc);doc.addEventListener('click',e=>{if(!e.target.closest('[data-theme-toggle]'))return;mode=mode==='dark'?'light':'dark';try{localStorage.setItem('vector-theme',mode);}catch{}docs.forEach(paint);});new MutationObserver(()=>{const b=doc.querySelector('[data-theme-toggle]');if(b&&b.textContent!==(mode==='dark'?'Light mode':'Dark mode'))paint(doc);}).observe(doc.documentElement,{childList:true,subtree:true});}window.vectorTheme={attach};attach(document);window.addEventListener('storage',e=>{if(e.key==='vector-theme'){mode=e.newValue==='dark'?'dark':'light';docs.forEach(paint);}});})();